using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;

namespace sv_91c569566b094864a14a373ca2012dba.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that hardcodes a user and persists
/// the identity via PersistentComponentState so the WASM runtime can rehydrate it.
/// </summary>
public sealed class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private readonly AuthenticationState _authenticationState;

    public PersistingAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentComponentState = persistentComponentState;

        // Build the hardcoded identity for bob@example.com
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        _authenticationState = new AuthenticationState(new ClaimsPrincipal(identity));

        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authenticationState);

    private Task OnPersistingAsync()
    {
        var principal = _authenticationState.User;
        if (principal.Identity?.IsAuthenticated == true)
        {
            var userInfo = new UserInfo
            {
                Email = principal.FindFirstValue(ClaimTypes.Email)!,
                Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
            };
            _persistentComponentState.PersistAsJson(nameof(UserInfo), userInfo);
        }

        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_91c569566b094864a14a373ca2012dba.Client;

/// <summary>
/// Client-side (WASM) AuthenticationStateProvider that reads persisted auth state
/// from PersistentComponentState, ensuring the user identity survives the handoff
/// from server prerendering to the WebAssembly runtime.
/// </summary>
public sealed class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly AuthenticationState _unauthenticated = new(new ClaimsPrincipal(new ClaimsIdentity()));
    private readonly AuthenticationState _authenticationState;

    public PersistentAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        if (!persistentComponentState.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) || userInfo is null)
        {
            _authenticationState = _unauthenticated;
            return;
        }

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, userInfo.Email),
            new(ClaimTypes.Email, userInfo.Email),
        };

        foreach (var role in userInfo.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        var identity = new ClaimsIdentity(claims, authenticationType: "Persisted");
        _authenticationState = new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authenticationState);
}

